39:   ctx: null,
40:   init() {
41:     if (!this.ctx) {
42:       const AudioCtor = window.AudioContext || window.webkitAudioContext;
43:       if (!AudioCtor) {
44:         return;
45:       }
46:       this.ctx = new AudioCtor();
47:     }
48:     if (this.ctx.state === 'suspended') {
49:       this.ctx.resume();
50:     }
51:   },
52:   playTone({ freq = 440, duration = 0.12, type = 'sine', volume = 0.04, sweep = 0, detune = 0 } = {}) {
53:     if (!this.ctx) {
54:       return;
55:     }
56:     const t = this.ctx.currentTime;
57:     const oscillator = this.ctx.createOscillator();
58:     const gain = this.ctx.createGain();
59:     oscillator.type = type;
60:     oscillator.frequency.setValueAtTime(freq, t);
61:     if (sweep !== 0) {
62:       oscillator.frequency.exponentialRampToValueAtTime(Math.max(30, freq + sweep), t + duration);
63:     }
64:     if (detune !== 0) {
65:       oscillator.detune.setValueAtTime(detune, t);
66:     }
67:     gain.gain.setValueAtTime(0.0001, t);
68:     gain.gain.exponentialRampToValueAtTime(volume, t + 0.02);
69:     gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
70:     oscillator.connect(gain);
71:     gain.connect(this.ctx.destination);
72:     oscillator.start(t);
73:     oscillator.stop(t + duration + 0.02);
74:   },
75:   pulse() {
