521: function fireWeapon() {
522:   if (game.cutsceneActive || game.health <= 0 || game.victory) return;
523:   const now = performance.now();
524:   if (now - game.lastShotAt < 180) {
525:     return;
526:   }
527:   game.lastShotAt = now;
528:   sound.init();
529:   sound.playTone({ freq: 620, duration: 0.06, type: 'square', volume: 0.04, sweep: 180 });
530: 
531:   const forward = new THREE.Vector3();
532:   camera.getWorldDirection(forward);
533:   const origin = player.position.clone().add(new THREE.Vector3(0, 0.35, 0));
534:   const end = origin.clone().add(forward.clone().multiplyScalar(18));
535: 
536:   let hitSomething = false;
537:   for (const enemy of game.enemies) {
538:     if (!enemy.hp) continue;
539:     const toEnemy = enemy.group.position.clone().sub(origin);
540:     const distance = toEnemy.length();
541:     if (distance < 15) {
542:       const projected = toEnemy.normalize();
543:       const dot = projected.dot(forward);
544:       if (dot > 0.7) {
545:         enemy.hp -= 1;
546:         createParticles(enemy.group.position.clone(), 0xff9f5d);
547:         createMuzzleFlash(origin, forward);
548:         if (enemy.hp <= 0) {
549:           enemy.group.visible = false;
550:           sound.playTone({ freq: 210, duration: 0.18, type: 'triangle', volume: 0.05, sweep: -120 });
551:           createParticles(enemy.group.position.clone(), 0xffd179);
552:         }
553:         hitSomething = true;
554:       }
555:     }
556:   }
557: 
558:   if (!hitSomething) {
559:     createMuzzleFlash(origin, forward);
560:   }
561: 
562:   if (game.relays.some((relay) => relay.active && relay.position.distanceTo(player.position) < 3.5)) {
563:     const relay = game.relays.find((r) => r.active && r.position.distanceTo(player.position) < 3.5);
564:     if (relay) {
565:       relay.group.rotation.y += 0.12;
566:     }
567:   }
568: 
569:   const beam = new THREE.Line(
570:     new THREE.BufferGeometry().setFromPoints([origin, end]),
571:     new THREE.LineBasicMaterial({ color: 0xffe7a3, transparent: true, opacity: 0.7 })
572:   );
573:   world.add(beam);
574:   game.sparkies.push({ mesh: beam, life: 0.08 });
575: }
