input.content:
 :root {
  --bg: #070b13;
  --panel: rgba(8, 15, 24, 0.78);
  --panel-border: rgba(132, 193, 255, 0.38);
  --text: #edf6ff;
  --muted: #8ea2bf;
  --cyan: #7fe7ff;
  --green: #93ffbf;
  --amber: #ffca6a;
  --red: #ff7373;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(ellipse at 50% 34%, #172a3d 0%, #09121e 47%, #020509 100%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}

canvas {
  display: block;
  width: 100vw;
  height: 100vh;
  background: #04080d;
}

#hud { position: fixed; inset: 0; pointer-events: none; }
#top-bar, #stats, #story-box { position: absolute; left: 20px; }
#top-bar { top: 20px; display: flex; gap: 12px; align-items: stretch; }
#stats { top: 96px; display: flex; gap: 12px; }
#story-box { bottom: 20px; max-width: min(500px, calc(100vw - 40px)); }

.panel {
  background: linear-gradient(135deg, rgba(13, 25, 37, .88), rgba(7, 13, 22, .76));
  border: 1px solid var(--panel-border);
  border-radius: 10px;
  box-shadow: 0 0 0 1px rgba(127, 231, 255, .08), 0 12px 40px rgba(1, 5, 12, .48);
  backdrop-filter: blur(12px);
  padding: 10px 12px;
}
.panel.small { min-width: 180px; }
.label {
  display: block;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: .16em;
  text-transform: uppercase;
  margin-bottom: 4px;
}
#status-text, #objective-text, #health-value, #relay-value, #story-text { font-size: 14px; }
#status-text { color: #b7eeff; }
#health-value { color: #9effc2; }
#relay-value { color: var(--cyan); }
#story-box { border-left: 2px solid var(--cyan); }
#story-box p { margin: 6px 0 0; line-height: 1.48; color: #e5eef7; }

#crosshair {
  position: absolute; left: 50%; top: 50%; width: 18px; height: 18px;
  transform: translate(-50%, -50%); pointer-events: none;
  filter: drop-shadow(0 0 5px rgba(127, 231, 255, .9));
}
#crosshair::before, #crosshair::after {
  content: ""; position: absolute; left: 50%; top: 50%;
  background: rgba(235, 250, 255, .92); transform: translate(-50%, -50%);
}
#crosshair::before { width: 2px; height: 18px; }
#crosshair::after { width: 18px; height: 2px; }

#message-overlay {
  position: fixed; z-index: 10; inset: 0; display: grid; place-items: center;
  background: rgba(2, 5, 10, .78); backdrop-filter: blur(12px);
}
.hidden { display: none !important; }
.message-card {
  width: min(460px, calc(100vw - 30px)); padding: 32px 28px 24px; text-align: center;
  background: linear-gradient(145deg, rgba(13, 27, 40, .97), rgba(5, 10, 18, .96));
  border: 1px solid rgba(127, 231, 255, .48); border-radius: 16px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, .6), inset 0 1px rgba(255,255,255,.06);
}
.message-card h1 { margin: 0 0 10px; font-size: clamp(2rem, 4vw, 3.25rem); }
.message-card p { margin: 0 0 18px; color: #a9bacb; line-height: 1.6; }
button {
  appearance: none; border: 0; border-radius: 999px; padding: 12px 22px;
  font-size: 15px; font-weight: 750; background: linear-gradient(135deg, #8af0ff, #829eff);
  color: #061116; cursor: pointer; box-shadow: 0 10px 30px rgba(76, 171, 226, .28);
  transition: filter .18s ease, transform .18s ease, border-color .18s ease;
}
button:hover { filter: brightness(1.09); transform: translateY(-1px); }
#touch-controls { display: none; }
body.cutscene-playing #hud, body.cutscene-playing #touch-controls { display: none !important; }

.cutscene-overlay {
  position: fixed; z-index: 20; inset: 0; display: flex; flex-direction: column; justify-content: flex-end;
  padding: clamp(20px, 7vw, 88px);
  background: radial-gradient(ellipse at 78% 28%, rgba(32, 113, 147, .18), transparent 38%),
    linear-gradient(180deg, rgba(2, 7, 13, .2), rgba(2, 7, 13, .2) 28%, rgba(2, 7, 13, .92));
}
.cutscene-overlay::before {
  content: ""; position: absolute; inset: 0; pointer-events: none; opacity: .16;
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(145, 211, 255, .09) 4px);
  mask-image: linear-gradient(transparent, black 50%);
}
.cutscene-topline {
  position: absolute; top: max(20px, env(safe-area-inset-top)); left: clamp(20px, 7vw, 88px); right: clamp(20px, 7vw, 88px);
  display: flex; justify-content: space-between; align-items: center; color: #b7c9dc;
  font-size: 11px; letter-spacing: .2em;
}
.cutscene-topline button, .cutscene-footer button {
  border: 1px solid rgba(148, 218, 255, .4); border-radius: 999px; padding: 10px 16px;
  background: rgba(8, 18, 30, .68); color: #eaf8ff; font-size: 11px; letter-spacing: .12em;
  box-shadow: none; pointer-events: auto;
}
.cutscene-card {
  position: relative; max-width: 820px; padding: clamp(22px, 4vw, 38px);
  background: linear-gradient(135deg, rgba(10, 20, 30, .94), rgba(7, 13, 23, .88));
  border: 1px solid rgba(127, 231, 255, .36); border-left: 3px solid var(--cyan); border-radius: 4px 16px 16px 4px;
  box-shadow: 0 24px 70px rgba(0,0,0,.5), inset 0 1px rgba(255,255,255,.05);
  animation: card-arrive .36s ease-out both;
}
@keyframes card-arrive { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
.cutscene-kicker { color: var(--cyan); font-size: 10px; letter-spacing: .22em; text-transform: uppercase; }
.cutscene-card h1 { margin: 12px 0; font-size: clamp(1.7rem, 5vw, 3.2rem); letter-spacing: -.04em; }
.cutscene-card p { max-width: 700px; min-height: 3.2em; color: #c1ccda; line-height: 1.72; font-size: clamp(14px, 2vw, 17px); }
.cutscene-footer { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-top: 20px; color: #8193a9; font-size: 11px; letter-spacing: .12em; }
.cutscene-footer button { background: var(--cyan); color: #061116; font-size: 13px; letter-spacing: .02em; font-weight: 700; }
.cutscene-footer button span { margin-left: 8px; }
.cutscene-choices { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 22px; }
.story-choice {
  display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 17px 18px; text-align: left;
  border: 1px solid rgba(127, 231, 255, .34); border-radius: 9px; background: rgba(8, 25, 37, .88);
  color: #eaf8ff; box-shadow: none; pointer-events: auto;
}
.story-choice:last-child { border-color: rgba(255, 191, 131, .38); background: rgba(34, 20, 17, .7); }
.story-choice strong { color: var(--cyan); font-size: 11px; letter-spacing: .18em; }
.story-choice:last-child strong { color: #ffc184; }
.story-choice span { color: #aebdcb; font-size: 13px; font-weight: 400; line-height: 1.45; }

@media (pointer: coarse), (max-width: 700px) {
  #top-bar { top: max(10px, env(safe-area-inset-top)); left: 10px; right: 10px; gap: 6px; }
  #stats { top: 76px; left: 10px; gap: 6px; }
  .panel { padding: 7px 9px; }
  #status-text, #objective-text, #health-value, #relay-value { font-size: 11px; }
  .label { font-size: 8px; }
  #story-box { left: 10px; right: 10px; bottom: calc(128px + env(safe-area-inset-bottom)); max-width: none; }
  #story-box p { font-size: 12px; line-height: 1.35; }
  #touch-controls { display: block; position: fixed; z-index: 5; inset: 0; pointer-events: none; touch-action: none; }
  #move-pad { position: absolute; left: max(18px, env(safe-area-inset-left)); bottom: max(18px, env(safe-area-inset-bottom)); width: 116px; height: 116px; pointer-events: auto; touch-action: none; }
  .pad-ring { position: absolute; inset: 0; border: 1px solid rgba(158, 218, 255, .32); border-radius: 50%; background: rgba(10, 22, 35, .43); box-shadow: inset 0 0 24px rgba(95, 183, 255, .1); }
  .pad-knob { position: absolute; width: 46px; height: 46px; left: 35px; top: 35px; border: 1px solid rgba(178, 236, 255, .75); border-radius: 50%; background: rgba(93, 186, 230, .34); box-shadow: 0 0 18px rgba(95, 203, 255, .22); }
  .pad-caption { position: absolute; left: 0; right: 0; bottom: -17px; text-align: center; color: rgba(206, 227, 247, .7); font-size: 8px; letter-spacing: .18em; }
  #look-pad { position: absolute; top: 110px; right: 0; bottom: 150px; width: 54%; pointer-events: auto; touch-action: none; }
  .touch-action { position: absolute; right: max(22px, env(safe-area-inset-right)); bottom: max(28px, env(safe-area-inset-bottom)); width: 74px; height: 74px; padding: 0; pointer-events: auto; touch-action: none; border: 1px solid rgba(255, 219, 155, .72); background: rgba(105, 71, 35, .62); color: #fff3d4; font-size: 11px; letter-spacing: .1em; box-shadow: 0 0 26px rgba(255, 179, 80, .16); }
  .touch-action.interact { right: max(108px, calc(env(safe-area-inset-right) + 108px)); bottom: max(38px, calc(env(safe-area-inset-bottom) + 38px)); width: 56px; height: 56px; border-color: rgba(127, 231, 255, .62); background: rgba(19, 84, 105, .62); color: #e4faff; }
  #crosshair { width: 14px; height: 14px; }
  #crosshair::before { height: 14px; }
  #crosshair::after { width: 14px; }
}
@media (max-width: 520px) {
  .cutscene-choices { grid-template-columns: 1fr; }
  .story-choice { padding: 12px 14px; }
  .cutscene-card { padding: 20px; }
  .cutscene-card p { min-height: 0; }
  .cutscene-footer { align-items: flex-start; font-size: 9px; }
}
@media (max-width: 420px) {
  .panel.small { min-width: 0; }
  #story-box { bottom: calc(122px + env(safe-area-inset-bottom)); }
  #story-text { font-size: 11px; }
}

